export async function runSchedule(graph, { limit, run }) {
  if (!Number.isInteger(limit) || limit < 1) {
    throw new TypeError('limit must be a positive integer');
  }

  // Validation
  const ids = new Set();
  const idToIndex = new Map();
  const idToNode = new Map();

  for (let i = 0; i < graph.length; i++) {
    const node = graph[i];
    if (ids.has(node.id)) {
      throw new Error(`Duplicate node: ${node.id}`);
    }
    ids.add(node.id);
    idToIndex.set(node.id, i);
    idToNode.set(node.id, node);
  }

  for (const node of graph) {
    for (const dep of node.deps) {
      if (!ids.has(dep)) {
        throw new Error(`Missing dependency: ${node.id} -> ${dep}`);
      }
    }
  }

  // Cycle detection using DFS
  const color = new Map();
  for (const node of graph) color.set(node.id, 0);

  function dfs(id) {
    color.set(id, 1);
    const node = idToNode.get(id);
    for (const dep of node.deps) {
      if (color.get(dep) === 1) {
        throw new Error('Dependency cycle detected');
      }
      if (color.get(dep) === 0) {
        dfs(dep);
      }
    }
    color.set(id, 2);
  }

  for (const node of graph) {
    if (color.get(node.id) === 0) {
      dfs(node.id);
    }
  }

  // Execution
  const results = new Array(graph.length);
  const pendingDeps = new Map();
  const dependents = new Map();
  const readyQueue = [];
  const launched = new Set();

  for (const node of graph) {
    pendingDeps.set(node.id, node.deps.length);
    dependents.set(node.id, []);
  }

  for (const node of graph) {
    for (const dep of node.deps) {
      dependents.get(dep).push(node.id);
    }
  }

  for (const node of graph) {
    if (node.deps.length === 0) {
      readyQueue.push(node.id);
    }
  }

  let activeCount = 0;
  let doneCount = 0;
  let rejected = false;

  let resolveAll, rejectAll;
  const allPromise = new Promise((resolve, reject) => {
    resolveAll = resolve;
    rejectAll = reject;
  });

  function schedule() {
    if (rejected) return;
    while (activeCount < limit && readyQueue.length > 0) {
      const nodeId = readyQueue.shift();
      if (launched.has(nodeId)) continue;
      launched.add(nodeId);
      activeCount++;

      const index = idToIndex.get(nodeId);
      const node = graph[index];

      Promise.resolve()
        .then(() => run(node))
        .then(value => {
          activeCount--;
          doneCount++;
          results[index] = value;

          for (const dependentId of dependents.get(nodeId)) {
            const newPending = pendingDeps.get(dependentId) - 1;
            pendingDeps.set(dependentId, newPending);
