            }
          }

          schedule();
          if (doneCount === graph.length) {
            resolveAll(results);
          }
        })
        .catch(err => {
          if (rejected) return;
          rejected = true;
          activeCount--;
          rejectAll(err);
        });
    }
    if (doneCount === graph.length) {
      resolveAll(results);
    }
  }

  schedule();
  return allPromise;
}
